/** The operations that answer `{ items, next }` pages and take `after`. */
export type PagedOperationId =
  | 'listResources'
  | 'listResourceActivity'
  | 'listFailingResources'
  | 'listJobs'
  | 'listApprovals'
  | 'listFindings'
  | 'listUnmanaged'
  | 'listAlarms'
  | 'listRecommendations'
  | 'search'
  | 'listAccessRequests'
  | 'listBudgets'
  | 'listBudgetPeriods';

/** The operations that answer a stream of server-sent events. */
export type EventStreamOperationId =
  | 'streamEvents';
